def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the rectangular frame.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 5)]
    # The two markers indicate the colors of the two diagonals.
    colors = {}
    for r, c, color in markers:
        if r < r0:
            diagonal = "tlbr" if c < (c0 + c1) / 2 else "trbl"
        elif r > r1:
            diagonal = "trbl" if c < (c0 + c1) / 2 else "tlbr"
        elif c < c0:
            diagonal = "tlbr" if r < (r0 + r1) / 2 else "trbl"
        else:
            diagonal = "trbl" if r < (r0 + r1) / 2 else "tlbr"
        colors[diagonal] = color

    out = [row[:] for row in grid]
    rm, cm = (r0 + r1) // 2, (c0 + c1) // 2
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            diagonal = "tlbr" if (r <= rm) == (c <= cm) else "trbl"
            if diagonal in colors:
                out[r][c] = colors[diagonal]
    return out
